    # X-Staff-Id was sent, the staff member too. Keep the staff member, the
    # person acting, so the rows satisfy field_change_one_actor.
    FieldChange = apps.get_model("pharmacy", "FieldChange")
    FieldChange.objects.filter(changed_by_staff__isnull=False).update(changed_by_user=None)


